def aggregate_sensor_readings(sensor_data, error_threshold):
    # Initialize variables
    aggregated_readings = {}
    total_readings = 0
    try:
        # Iterate over sensor data
        for reading in sensor_data:
            # Check for valid readings
            if reading["value"] > error_threshold:
                aggregated_readings[reading["sensor_id"]] = reading["value"]
                total_readings += 1
        # Calculate average reading
        average_reading = sum(aggregated_readings.values()) / total_readings if total_readings > 0 else 0
        return average_reading
    except KeyError as e:
        # Log and re-raise exception
        print("Error: Invalid sensor data format")
        raise e
    except ZeroDivisionError as e:
        # Log and return default value
        print("Error: No valid readings found")
        return 0

