    try:
        # Validate input date string
        if not isinstance(date_string, str) or len(date_string) != 10:
            raise ValueError("Invalid date string format. Expected 'YYYY-MM-DD'.")
        year, month, day = date_string.split('-')
        # Basic input validation for year, month, day
        if not (year.isdigit() and month.isdigit() and day.isdigit()):
            raise ValueError("Invalid date string. Non-numeric values found.")
        year, month, day = int(year), int(month), int(day)
        if not (1 <= month <= 12 and 1 <= day <= 31):
