    # Parse timestamp string into datetime object
    try:
        dt = datetime.datetime.strptime(timestamp_str, format_str)
    except ValueError:
        # Handle invalid timestamp format
        print("Error: Invalid timestamp format")
        return None
    # Normalize datetime object to UTC
