def calculate_mandelbrot_set(xmin, xmax, ymin, ymax, width, height, max_iterations):
    if not isinstance(xmin, (int, float)) or not isinstance(xmax, (int, float)) or not isinstance(ymin, (int, float)) or not isinstance(ymax, (int, float)):
        raise ValueError("xmin, xmax, ymin, ymax must be numbers")
    if width <= 0 or height <= 0:
        raise ValueError("width and height must be positive integers")
    if max_iterations <= 0:
        raise ValueError("max_iterations must be a positive integer")
    result = {}
    for i in range(width):
        for j in range(height):
            x = xmin + (xmax - xmin) * i / width
            y = ymin + (ymax - ymin) * j / height
            c = complex(x, y)
            z = complex(0, 0)
            iteration = 0
            while iteration < max_iterations and abs(z) < 2:
                z = z * z + c
                iteration += 1
            result[(i, j)] = iteration
    return result

