def convert_length_units(length, from_unit, to_unit):
    if from_unit not in ["meters", "centimeters", "millimeters", "kilometers"]:
        raise ValueError("Invalid from_unit. Supported units are: meters, centimeters, millimeters, kilometers")
    if to_unit not in ["meters", "centimeters", "millimeters", "kilometers"]:
        raise ValueError("Invalid to_unit. Supported units are: meters, centimeters, millimeters, kilometers")
    conversion_factors = {
        "meters": 1,
        "centimeters": 100,
        "millimeters": 1000,
        "kilometers": 0.001
    }
    try:
        length = float(length)
    except ValueError:
        raise ValueError("Invalid length. Please enter a numeric value.")
    base_length = length / conversion_factors[from_unit]
    converted_length = base_length * conversion_factors[to_unit]
    return converted_length

